CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), account_code TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE account_permissions (user_id UUID NOT NULL, account_id UUID NOT NULL REFERENCES accounts(id), permission TEXT NOT NULL CHECK(permission IN ('monitor:read','export:read')), PRIMARY KEY(user_id,account_id,permission));
CREATE TABLE instruments (id TEXT PRIMARY KEY, exchange TEXT NOT NULL CHECK(exchange IN ('NFO','BFO')), symbol TEXT NOT NULL, underlying TEXT NOT NULL, expiry DATE NOT NULL, strike NUMERIC(18,4), option_type TEXT, quantity_unit TEXT NOT NULL, lot_size INTEGER NOT NULL CHECK(lot_size>0), multiplier NUMERIC(18,8) NOT NULL, effective_from DATE NOT NULL, effective_to DATE);
CREATE TABLE position_snapshots (account_id UUID NOT NULL REFERENCES accounts(id), strategy_id TEXT NOT NULL, instrument_id TEXT NOT NULL REFERENCES instruments(id), session_id TEXT NOT NULL, opening_qty BIGINT NOT NULL, buy_filled_qty BIGINT NOT NULL, sell_filled_qty BIGINT NOT NULL, net_qty BIGINT NOT NULL, working_buy_qty BIGINT NOT NULL, working_sell_qty BIGINT NOT NULL, avg_open_price NUMERIC(20,8), mark_price NUMERIC(20,8), realized_pnl NUMERIC(24,8), unrealized_pnl NUMERIC(24,8), costs NUMERIC(24,8), net_pnl NUMERIC(24,8), currency CHAR(3) NOT NULL, valuation_status TEXT NOT NULL, reconciliation_status TEXT NOT NULL, revision BIGINT NOT NULL, as_of TIMESTAMPTZ NOT NULL, PRIMARY KEY(account_id,strategy_id,instrument_id,session_id));
CREATE TABLE fills (execution_id TEXT PRIMARY KEY, order_id TEXT NOT NULL, account_id UUID NOT NULL REFERENCES accounts(id), instrument_id TEXT NOT NULL REFERENCES instruments(id), side TEXT NOT NULL CHECK(side IN ('BUY','SELL')), quantity BIGINT NOT NULL CHECK(quantity>0), price NUMERIC(20,8) NOT NULL, exchange_time TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL, revision BIGINT NOT NULL);
CREATE INDEX fills_scope_time_idx ON fills(account_id,instrument_id,exchange_time DESC);
